import{_ as a,o as t,c as r,a2 as l}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"文档地图与维护","description":"Hearth 的单一文档源、目录结构、阅读层级、双语规则和更新流程。","frontmatter":{"title":"文档地图与维护","description":"Hearth 的单一文档源、目录结构、阅读层级、双语规则和更新流程。","outline":[2,3]},"headers":[],"relativePath":"reference/source-map.md","filePath":"reference/source-map.md","lastUpdated":1793752688000}'),i={name:"reference/source-map.md"};function h(o,e,d,s,n,c){return t(),r("div",null,[...e[0]||(e[0]=[l('<p class="eyebrow">DOCUMENTATION MAP</p><h1 id="文档地图与维护" tabindex="-1">文档地图与维护 <a class="header-anchor" href="#文档地图与维护" aria-label="Permalink to &quot;文档地图与维护&quot;">​</a></h1><p class="lead">所有正式文档只存放在仓库的 <code>docs/</code>。文档站由这个目录直接构建，README 只负责仓库入口，因此仓库内容与线上站点始终是同一份文档。</p><h2 id="文档地图" tabindex="-1">文档地图 <a class="header-anchor" href="#文档地图" aria-label="Permalink to &quot;文档地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区域</th><th>内容</th><th>入口</th></tr></thead><tbody><tr><td>设计说明</td><td>定位、原则、取舍、架构与当前状态</td><td><a href="/hearth-os/design/">设计说明</a></td></tr><tr><td>架构细节</td><td>协议、控制面、执行器、安全、记忆与评估</td><td><a href="/hearth-os/architecture/overview.html">总体架构</a></td></tr><tr><td>交付路线</td><td>Stage 0–6、D 增量、工作包与 MVP</td><td><a href="/hearth-os/delivery/">交付路线</a></td></tr><tr><td>开发日志</td><td>每天一段概述，加上提交、具体修改与作者</td><td><a href="/hearth-os/log/day-02.html">Day02</a></td></tr><tr><td>附录</td><td>工程、风险、决策、术语、清单与归档</td><td><a href="/hearth-os/reference/">附录</a></td></tr></tbody></table><h2 id="阅读层级" tabindex="-1">阅读层级 <a class="header-anchor" href="#阅读层级" aria-label="Permalink to &quot;阅读层级&quot;">​</a></h2><ol><li><strong>设计说明</strong>回答为什么做、边界在哪、关键取舍是什么；</li><li><strong>交付路线</strong>把设计变成 Stage 0–6 的能力门槛和施工顺序；</li><li><strong>Stage 页面</strong>说明前置条件、阶段出口和本阶段不做什么；</li><li><strong>D 增量页</strong>给出可独立施工和验收的纵向切片；</li><li><strong>四个工作包</strong>进一步说明实施步骤、工程落点、接口和失败恢复。</li></ol><p>先确认当前阶段的范围和出口，再进入具体开发页；不要从单个工作包反推整个产品范围。</p><h2 id="三条阅读路径" tabindex="-1">三条阅读路径 <a class="header-anchor" href="#三条阅读路径" aria-label="Permalink to &quot;三条阅读路径&quot;">​</a></h2><h3 id="理解产品与设计" tabindex="-1">理解产品与设计 <a class="header-anchor" href="#理解产品与设计" aria-label="Permalink to &quot;理解产品与设计&quot;">​</a></h3><ol><li><a href="/hearth-os/design/">项目设计与取舍</a></li><li><a href="/hearth-os/architecture/overview.html">总体架构与数据流</a></li><li><a href="/hearth-os/architecture/domain-model.html">领域模型与协议</a></li><li><a href="/hearth-os/architecture/execution-safety.html">执行安全与副作用</a></li><li><a href="/hearth-os/architecture/evaluation.html">评估体系</a></li></ol><h3 id="查看交付计划" tabindex="-1">查看交付计划 <a class="header-anchor" href="#查看交付计划" aria-label="Permalink to &quot;查看交付计划&quot;">​</a></h3><ol><li><a href="/hearth-os/delivery/">交付路线与实施计划</a></li><li><a href="/hearth-os/delivery/stage-0.html">Stage 0 · 定义与原型</a></li><li><a href="/hearth-os/delivery/stage-1.html">Stage 1 · 持久内核与 MVP</a></li><li><a href="/hearth-os/reference/full-roadmap.html">完整路线图归档</a></li></ol><h3 id="直接开工" tabindex="-1">直接开工 <a class="header-anchor" href="#直接开工" aria-label="Permalink to &quot;直接开工&quot;">​</a></h3><ol><li><a href="/hearth-os/delivery/stage-0.html">Stage 0 · 定义与原型</a></li><li><a href="/hearth-os/delivery/stage-0/d0-1.html">D0.1 · 产品楔子与真实任务基线</a></li><li><a href="/hearth-os/reference/engineering.html">工程实施与仓库结构</a></li><li><a href="/hearth-os/reference/risks.html">风险与 Kill Criteria</a></li></ol><h2 id="主题页面与完整归档" tabindex="-1">主题页面与完整归档 <a class="header-anchor" href="#主题页面与完整归档" aria-label="Permalink to &quot;主题页面与完整归档&quot;">​</a></h2><ul><li>主题页面是日常阅读和维护的主路径，按设计、交付、日志和附录组织。</li><li><a href="/hearth-os/reference/full-roadmap.html">完整路线图归档</a>保留长文细节，适合检索、引用和差异核对。</li><li>归档页与主题页面都位于 <code>docs/</code>，不是两个独立文档源。</li><li>修改事实、协议或阶段门槛时，同时更新主题页面、归档页和英文镜像。</li></ul><h2 id="维护流程" tabindex="-1">维护流程 <a class="header-anchor" href="#维护流程" aria-label="Permalink to &quot;维护流程&quot;">​</a></h2><ol><li>先修改中文页面，确认结论、边界和链接仍然准确。</li><li>在 <code>docs/en/</code> 的相同相对路径创建或更新英文镜像。</li><li>更新相关入口、侧栏和交叉链接，避免留下失效路径。</li><li>运行 <code>npm run docs:build</code>，先消除构建错误和站内死链。</li><li>在本地预览中检查长表格、代码块、移动端宽度和语言切换。</li></ol><h2 id="提交前检查" tabindex="-1">提交前检查 <a class="header-anchor" href="#提交前检查" aria-label="Permalink to &quot;提交前检查&quot;">​</a></h2><ul><li>正式文档只修改 <code>docs/</code>，不要新增第二个文档根目录。</li><li>中文与英文页面路径对应，标题层级和列表数量一致。</li><li>交付路线保持“设计 → 交付 → Stage → D 增量 → 工作包”的层级。</li><li>README 只保留项目简介、快速开始和文档导航，不复制长篇正文。</li><li>开发日志每天只保留一段概述和提交明细，不恢复日志首页或模板。</li><li>不提交 <code>docs/.vitepress/dist</code>、缓存、本地密钥或无证据的完成声明。</li></ul><h2 id="文档与发版边界" tabindex="-1">文档与发版边界 <a class="header-anchor" href="#文档与发版边界" aria-label="Permalink to &quot;文档与发版边界&quot;">​</a></h2><ul><li>当前文档描述规格、设计判断和开发计划，不代表产品已经发布。</li><li>开发日志按天记录概述、提交、具体修改与作者，不冒充产品发版说明。</li><li>只有实现开始并形成可安装版本后，才维护正式版本号和发布说明。</li></ul>',23)])])}const m=a(i,[["render",h]]);export{u as __pageData,m as default};
